from collections import OrderedDict

def lru_sim(cap, keys):
    cache = OrderedDict()
    hits = 0

    for key in keys:
        if key in cache:
            hits += 1
            cache.move_to_end(key)
        else:
            cache[key] = True
            if len(cache) > cap:
                cache.popitem(last=False)

    return hits
```

